		protected override void AttachButton_Click(object sender, EventArgs e)
		{
			if (!Env.Security.ConsolAttachDetachShipmentAfterCutOffDate.IsAllowed
				&& ParentConsol != null && ParentConsol.Validation.IsLateThanCutOffDate)
			{
				Globals.Message.ShowError(Res.GetString("6025cc91-02c6-4e29-9aa8-7450d053034a", "Cannot attach any AWB Co-Load consol to the consol {0} as the consol's Cut Off Date has passed.\r\n\r\n{1}",
					ParentConsol.JK_UniqueConsignRef,
					Env.Security.GetErrorMessageForNotAllowed(Env.Security.ConsolAttachDetachShipmentAfterCutOffDate)));

				return;
			}

			base.AttachButton_Click(sender, e);
		}
